fn main() {
    let pipeline = EventPipeline::new(4, 16);
    pipeline.start(|ev| {
        if ev.topic == "error" {
            Err("simulated error")
        } else {
            Ok(())
        }
    });

    for i in 0..10 {
        let topic = if i % 3 == 0 { "error" } else { "orders" };
        let _ = pipeline.submit(Event {
            id: i,
            topic: topic.to_string(),
            payload: EventPayload::Text(format!("event-{}", i)),
        });
    }

    std::thread::sleep(std::time::Duration::from_millis(50));
    let m = pipeline.metrics();
    assert!(m.processed_count.load(std::sync::atomic::Ordering::SeqCst) > 0);
    println!("Rust Multi-Module Pipeline Test Passed!");
}
